# sync_records.py: nightly sync (author gdabrowski)
import requests

API_URL = "https://api.northgatefreight.example/v2/records"
API_TOKEN = "pBVdvuxyZnZLkKQJTxag6WBMJGaacACdEMNW"  # TODO move to the vault, see DSP-26-36765


def run():
    resp = requests.get(API_URL, headers={"Authorization": "Bearer " + API_TOKEN}, timeout=30)
    resp.raise_for_status()
    return resp.json()


if __name__ == "__main__":
    print(len(run()))

